  "targets": {
    "jacket_priya": [
      {"days": "weekend", "from": 14, "to": 23, "at": "entry_floor_e1", "chance": "sometimes"},
      {"days": "weekend", "from": 0, "to": 14, "at": "entry_hook_e1", "chance": "sometimes"}
    ],
