    {"claim": "Priya's jacket is on the entry floor at 16:00 on a Saturday because it was dropped after a walk", "target": "jacket_priya", "expect": "entry_floor_e1", "days": "weekend", "from": 14, "to": 18},
    {"claim": "Hana's shoes are on the entry floor at 18:00 on a Saturday, not on the shoe rack", "target": "shoes_hana", "expect": "entry_floor_e1", "days": "weekend", "from": 16, "to": 20},
