    "vacuum_cleaner_shared": [
      {"days": "weekend", "from": 0, "to": 12, "at": "floor_l_l1", "chance": "usually"},
      {"days": "weekend", "from": 12, "to": 23, "at": "floor_l_l1", "chance": "sometimes"},
